fn create_row(n: u8) -> Vec<u8> {
    // Pre-allocate a Vec of length `n` (cast to usize for capacity)
    let mut row = Vec::with_capacity(n as usize);
    // Populate it with values 0, 1, 2, ..., n-1
    for i in 0..n {
        row.push(i);
    }
    row
}

fn indices(n: u8) -> Vec<Vec<u8>> {
    // The "grid" is a Vec containing exactly one row,
    // which is the vector returned by create_row(n).
    vec![create_row(n)]
}

// Example usage and simple tests
fn main() {
    // n = 5 -> one row [0, 1, 2, 3, 4]
    let grid = indices(5);
    assert_eq!(grid.len(), 1);
    assert_eq!(grid[0], vec![0, 1, 2, 3, 4]);

    // n = 0 -> one empty row
    let grid_empty = indices(0);
    assert_eq!(grid_empty.len(), 1);
    assert!(grid_empty[0].is_empty());

    println!("All tests passed.");
}